-- Crear tabla sucursales
CREATE TABLE sucursales (
    branch_id VARCHAR(8) PRIMARY KEY,
    store_type VARCHAR(30),
    size_m2 INT,
    categories VARCHAR(MAX),
    subcategories VARCHAR(MAX),
    country VARCHAR(50),
    city VARCHAR(50),
    address VARCHAR(150),
    phone VARCHAR(20),
    email VARCHAR(100),
    opening_hours VARCHAR(50),
    num_empleados INT
);

